/**
 * @file load_inertial.h
 * @brief Defines equivalent loads generated by prescribed rigid-body acceleration.
 *
 * `InertialLoad` converts translational and rotational rigid-body acceleration
 * into equivalent nodal inertia forces. Distributed structural mass is handled
 * through density-scaled element integration, while concentrated point masses
 * additionally contribute direct translational force and rotary inertia moments.
 *
 * @see Neumann
 * @see model::StructuralElement
 * @see model::PointElement
 * @see PointMassSection
 *
 * @author Finn Eggers
 * @date 17.09.2026
 */

#pragma once

#include "neumann.h"
#include "../../data/region.h"

#include <memory>
#include <string>

namespace fem::bc {

/**
 * @brief Applies inertia forces associated with a prescribed rigid-body motion.
 *
 * Let `c` be the reference center, `a0` its translational acceleration, `omega`
 * the angular velocity and `alpha` the angular acceleration. For a material
 * point at global position `x`, with
 *
 *     r = x - c,
 *
 * the rigid-body acceleration represented by this load is
 *
 *     a(x) = a0 + alpha x r + omega x (omega x r).
 *
 * The equivalent distributed inertia contribution is
 *
 *     f_e = -integral_Omega_e rho N^T a(x) dOmega.
 *
 * A concentrated point mass `m` receives `-m a(x)`. If diagonal rotary inertia
 * `J` is present, the nodal moment additionally contains
 *
 *     M = -(J alpha + omega x (J omega)).
 *
 * The optional amplitude scales the complete force and moment contribution.
 */
struct InertialLoad : Neumann {
    // Types
    using Ptr = std::shared_ptr<InertialLoad>;

    // Rigid-body kinematic definition in global coordinates
    Vec3 center_     = {0, 0, 0};
    Vec3 center_acc_ = {0, 0, 0};
    Vec3 omega_      = {0, 0, 0};
    Vec3 alpha_      = {0, 0, 0};

    // Structural elements whose distributed or compiled point mass contributes
    SPtr<model::ElementRegion> region_ = nullptr;

    // Include auxiliary PointElements created after compilation by native
    // POINTMASS definitions. These objects do not belong to the dense ELSET
    // namespace and therefore require a separate traversal.
    bool consider_point_masses_ = false;

    // Construction
    InertialLoad() = default;
    ~InertialLoad() override = default;

    // Integrate -rho N^T a over distributed mass and add the corresponding
    // concentrated force/moment terms for point masses.
    void apply(model::ModelData& model_data, model::Field& rhs,
               Precision time, bool ignore_amplitude = false) override;

    // Diagnostics
    std::string str() const override;
};

} // namespace fem::bc
